const TOPICS={
 WQ027:{category:'psychology',author:'Viktor E. Frankl',work:"Man's Search for Meaning — Logotherapy in a Nutshell, The Meaning of Suffering",date:'1959 / later editions',original:'When we are no longer able to change a situation, we are challenged to change ourselves.',original_language:'en',source:'https://www.mindwisepsychology.net/uploads/2/3/5/9/23593680/viktor_frankel_mans_search_for_meaning.pdf',locator:'The Meaning of Suffering, p. 117 in the scanned English edition',slug:'frankl-change-ourselves',concept:'A dignified mid-20th-century editorial portrait of Viktor Frankl in a quiet study. A closed road outside the window ends at a stone wall, while inside a person turns from the blocked path toward a desk, opens a notebook and begins to redraw a new route. The metaphor is inner change when circumstances cannot be altered.',q:{uk:'«Коли ми вже не можемо змінити ситуацію, перед нами постає виклик — змінити себе». — Віктор Франкл',ru:'«Когда мы больше не можем изменить ситуацию, перед нами встаёт задача — изменить себя». — Виктор Франкл',pl:'„Kiedy nie jesteśmy już w stanie zmienić sytuacji, stajemy przed wyzwaniem, by zmienić samych siebie.” — Viktor E. Frankl',en:'“When we are no longer able to change a situation, we are challenged to change ourselves.” — Viktor E. Frankl',sv:'”När vi inte längre kan förändra en situation utmanas vi att förändra oss själva.” — Viktor E. Frankl',de:'„Wenn wir eine Situation nicht mehr ändern können, sind wir aufgefordert, uns selbst zu ändern.“ — Viktor E. Frankl',es:'«Cuando ya no podemos cambiar una situación, tenemos el desafío de cambiarnos a nosotros mismos». — Viktor E. Frankl',fr:'«Lorsque nous ne pouvons plus changer une situation, nous sommes mis au défi de nous changer nous-mêmes.» — Viktor E. Frankl',it:'«Quando non siamo più in grado di cambiare una situazione, siamo chiamati a cambiare noi stessi.» — Viktor E. Frankl',pt:'“Quando já não podemos mudar uma situação, somos desafiados a mudar a nós mesmos.” — Viktor E. Frankl',id:'“Ketika kita tidak lagi mampu mengubah suatu keadaan, kita ditantang untuk mengubah diri kita sendiri.” — Viktor E. Frankl',tr:'“Bir durumu artık değiştiremiyorsak, kendimizi değiştirme sınavıyla karşı karşıyayız.” — Viktor E. Frankl',ar:'«حين لا نعود قادرين على تغيير موقف ما، يصبح التحدي أن نغيّر أنفسنا.» — فيكتور فرانكل'},insight:{uk:'коли зовнішні обставини справді не піддаються нашому контролю, простір свободи може залишатися у власній відповіді, ставленні та наступному кроці',ru:'когда внешние обстоятельства действительно не поддаются нашему контролю, пространство свободы может оставаться в нашей реакции, отношении и следующем шаге',pl:'gdy zewnętrznych okoliczności naprawdę nie da się zmienić, przestrzeń wolności może pozostać w naszej odpowiedzi, postawie i kolejnym kroku',en:'when external circumstances truly cannot be changed, a field of freedom can remain in our response, our attitude and our next step',sv:'när de yttre omständigheterna verkligen inte går att förändra kan ett utrymme för frihet finnas kvar i vårt svar, vår hållning och vårt nästa steg',de:'wenn äußere Umstände tatsächlich nicht veränderbar sind, kann ein Raum der Freiheit in unserer Antwort, unserer Haltung und unserem nächsten Schritt bleiben',es:'cuando las circunstancias externas realmente no pueden cambiarse, aún puede quedar un espacio de libertad en nuestra respuesta, nuestra actitud y nuestro siguiente paso',fr:'lorsque les circonstances extérieures ne peuvent réellement plus être changées, un espace de liberté peut subsister dans notre réponse, notre attitude et notre prochain pas',it:'quando le circostanze esterne non possono davvero essere cambiate, può restare uno spazio di libertà nella nostra risposta, nel nostro atteggiamento e nel passo successivo',pt:'quando as circunstâncias externas realmente não podem ser mudadas, ainda pode existir um espaço de liberdade na nossa resposta, na nossa atitude e no próximo passo',id:'ketika keadaan di luar diri benar-benar tidak dapat diubah, ruang kebebasan masih dapat tersisa dalam respons, sikap, dan langkah kita berikutnya',tr:'dış koşullar gerçekten değiştirilemiyorsa bile, özgürlük alanı verdiğimiz yanıtta, tutumumuzda ve bir sonraki adımımızda kalabilir',ar:'حين يتعذر فعلًا تغيير الظروف الخارجية، قد تبقى مساحة للحرية في استجابتنا وموقفنا والخطوة التالية التي نختارها'}},
 WQ028:{category:'philosophy',author:'Seneca',work:'De Brevitate Vitae, I.3',date:'c. 49 CE',original:'Non exiguum temporis habemus, sed multum perdidimus.',original_language:'la',source:'https://wwww.thelatinlibrary.com/sen/sen.brevita.shtml',locator:'De Brevitate Vitae, I.3',slug:'seneca-time-we-lose',concept:'A restrained Roman study at late afternoon. Seneca is represented through a dignified sculptural or art-historical portrait treatment. Sunlight moves across a water clock and a stack of untouched wax tablets while grains continue to fall, making lost time visible without melodrama.',q:{uk:'«У нас не мало часу — ми багато його втрачаємо». — Сенека',ru:'«У нас не мало времени — мы много его теряем». — Сенека',pl:'„Nie mamy mało czasu — wiele go tracimy.” — Seneka',en:'“It is not that we have little time, but that we waste much of it.” — Seneca',sv:'”Det är inte så att vi har ont om tid; vi slösar bort mycket av den.” — Seneca',de:'„Wir haben nicht zu wenig Zeit; wir verlieren viel davon.“ — Seneca',es:'«No es que tengamos poco tiempo; es que perdemos mucho». — Séneca',fr:'«Ce n’est pas que nous ayons peu de temps ; c’est que nous en perdons beaucoup.» — Sénèque',it:'«Non è che abbiamo poco tempo; ne perdiamo molto.» — Seneca',pt:'“Não é que tenhamos pouco tempo; perdemos muito dele.” — Sêneca',id:'“Bukan karena waktu kita sedikit; kita justru menyia-nyiakan banyak darinya.” — Seneca',tr:'“Az zamanımız yok değil; zamanımızın çoğunu yitiriyoruz.” — Seneca',ar:'«ليس لدينا وقت قليل، بل نحن نُضيّع الكثير منه.» — سينيكا'},insight:{uk:'проблема часто не в нестачі годин, а в тому, що увага й час непомітно розчиняються в речах, які ми самі не вважали важливими',ru:'проблема часто не в нехватке часов, а в том, что внимание и время незаметно растворяются в вещах, которые мы сами не считали важными',pl:'problemem często nie jest brak godzin, lecz to, że uwaga i czas niepostrzeżenie rozpływają się w sprawach, których sami nie uznawaliśmy za ważne',en:'the problem is often not a shortage of hours but the quiet loss of attention and time to things we ourselves did not consider important',sv:'problemet är ofta inte bristen på timmar utan att uppmärksamhet och tid tyst försvinner till sådant vi själva inte tyckte var viktigt',de:'das Problem ist oft nicht ein Mangel an Stunden, sondern dass Aufmerksamkeit und Zeit unbemerkt an Dinge verloren gehen, die wir selbst nicht für wichtig hielten',es:'el problema no suele ser la falta de horas, sino que la atención y el tiempo se disuelven sin darnos cuenta en cosas que nosotros mismos no considerábamos importantes',fr:'le problème n’est souvent pas le manque d’heures, mais le fait que notre attention et notre temps se dissipent discrètement dans des choses que nous ne jugions nous-mêmes pas importantes',it:'il problema spesso non è la mancanza di ore, ma il modo in cui attenzione e tempo si disperdono senza che ce ne accorgiamo in cose che noi stessi non ritenevamo importanti',pt:'o problema muitas vezes não é a falta de horas, mas o modo como atenção e tempo se perdem silenciosamente em coisas que nós mesmos não considerávamos importantes',id:'masalahnya sering bukan kekurangan jam, melainkan perhatian dan waktu yang diam-diam habis untuk hal-hal yang sebenarnya tidak kita anggap penting',tr:'sorun çoğu zaman saatlerin azlığı değil, dikkatin ve zamanın bizim bile önemli görmediğimiz şeylerde sessizce eriyip gitmesidir',ar:'المشكلة غالبًا ليست قلة الساعات، بل تسرّب الانتباه والوقت بهدوء إلى أمور لم نكن نحن أنفسنا نعدّها مهمة'}},
 WQ029:{category:'history',author:'Nelson Mandela',work:'Long Walk to Freedom',date:'1994',original:'I learned that courage was not the absence of fear, but the triumph over it.',original_language:'en',source:'https://www.nelsonmandela.org/news/entry/head-and-heart-the-lessons-of-leadership-from-nelson-mandela',locator:'Nelson Mandela Foundation quotation from Long Walk to Freedom',slug:'mandela-courage-fear',concept:'A dignified portrait of Nelson Mandela in a quiet corridor opening toward daylight. A person pauses before stepping through a shadowed doorway, visibly afraid but moving forward. The image treats courage as action in the presence of fear, not as invulnerability.',q:{uk:'«Я зрозумів, що мужність — це не відсутність страху, а перемога над ним». — Нельсон Мандела',ru:'«Я понял, что мужество — это не отсутствие страха, а победа над ним». — Нельсон Мандела',pl:'„Nauczyłem się, że odwaga nie jest brakiem strachu, lecz zwycięstwem nad nim.” — Nelson Mandela',en:'“I learned that courage was not the absence of fear, but the triumph over it.” — Nelson Mandela',sv:'”Jag lärde mig att mod inte är frånvaro av rädsla, utan segern över den.” — Nelson Mandela',de:'„Ich habe gelernt, dass Mut nicht die Abwesenheit von Angst ist, sondern der Sieg über sie.“ — Nelson Mandela',es:'«Aprendí que el valor no era la ausencia de miedo, sino el triunfo sobre él». — Nelson Mandela',fr:'«J’ai appris que le courage n’était pas l’absence de peur, mais la victoire sur elle.» — Nelson Mandela',it:'«Ho imparato che il coraggio non è l’assenza di paura, ma il trionfo su di essa.» — Nelson Mandela',pt:'“Aprendi que a coragem não era a ausência do medo, mas o triunfo sobre ele.” — Nelson Mandela',id:'“Saya belajar bahwa keberanian bukanlah ketiadaan rasa takut, melainkan kemenangan atas rasa takut itu.” — Nelson Mandela',tr:'“Cesaretin korkunun yokluğu değil, korkuya karşı kazanılan zafer olduğunu öğrendim.” — Nelson Mandela',ar:'«تعلّمت أن الشجاعة ليست غياب الخوف، بل الانتصار عليه.» — نيلسون مانديلا'},insight:{uk:'мужність не вимагає перестати боятися; вона починається там, де страх уже не має останнього слова щодо нашої дії',ru:'мужество не требует перестать бояться; оно начинается там, где страх уже не получает последнего слова в наших действиях',pl:'odwaga nie wymaga, by przestać się bać; zaczyna się tam, gdzie strach przestaje mieć ostatnie słowo w sprawie naszego działania',en:'courage does not require us to stop feeling fear; it begins when fear no longer has the final say over what we do',sv:'mod kräver inte att rädslan försvinner; det börjar när rädslan inte längre får sista ordet om vad vi gör',de:'Mut verlangt nicht, dass Angst verschwindet; er beginnt dort, wo die Angst nicht mehr das letzte Wort über unser Handeln hat',es:'el valor no exige dejar de sentir miedo; comienza cuando el miedo deja de tener la última palabra sobre lo que hacemos',fr:'le courage n’exige pas que la peur disparaisse ; il commence lorsque la peur n’a plus le dernier mot sur ce que nous faisons',it:'il coraggio non richiede che la paura scompaia; comincia quando la paura non ha più l’ultima parola sulle nostre azioni',pt:'a coragem não exige que o medo desapareça; ela começa quando o medo deixa de ter a palavra final sobre o que fazemos',id:'keberanian tidak menuntut hilangnya rasa takut; keberanian dimulai ketika rasa takut tidak lagi menentukan tindakan kita',tr:'cesaret korkunun ortadan kalkmasını gerektirmez; korku ne yapacağımız konusunda son sözü söylemediğinde başlar',ar:'الشجاعة لا تتطلب اختفاء الخوف؛ بل تبدأ حين لا يعود الخوف صاحب الكلمة الأخيرة في ما نفعله'}},
 WQ030:{category:'literature',author:'Virginia Woolf',work:"A Room of One's Own, Chapter 4",date:'1929',original:'There is no gate, no lock, no bolt that you can set upon the freedom of my mind.',original_language:'en',source:'https://en.wikisource.org/wiki/A_Room_of_One%27s_Own_%28Hogarth_1929%29/Chapter_4',locator:'Chapter 4; exact contiguous excerpt from the sentence beginning “Lock up your libraries if you like…”',slug:'woolf-freedom-of-mind',concept:'A refined 1929 literary interior associated with Virginia Woolf, rendered as a dignified editorial portrait rather than fake footage. A locked library door remains in shadow while light enters through an open high window and falls across a blank page, making intellectual freedom visible beyond physical barriers.',q:{uk:'«Немає ні воріт, ні замка, ні засуву, якими можна було б ув’язнити свободу мого розуму». — Вірджинія Вулф',ru:'«Нет ни ворот, ни замка, ни засова, которыми можно было бы запереть свободу моего разума». — Вирджиния Вулф',pl:'„Nie ma bramy, zamka ani zasuwy, którymi można by zamknąć wolność mojego umysłu.” — Virginia Woolf',en:'“There is no gate, no lock, no bolt that you can set upon the freedom of my mind.” — Virginia Woolf',sv:'”Det finns ingen grind, inget lås och ingen regel som kan stänga in mitt sinnes frihet.” — Virginia Woolf',de:'„Es gibt kein Tor, kein Schloss und keinen Riegel, mit dem man die Freiheit meines Geistes einsperren könnte.“ — Virginia Woolf',es:'«No hay puerta, cerradura ni cerrojo que pueda imponerse a la libertad de mi mente». — Virginia Woolf',fr:'«Il n’existe ni grille, ni serrure, ni verrou que l’on puisse imposer à la liberté de mon esprit.» — Virginia Woolf',it:'«Non esiste cancello, serratura o chiavistello che possa essere imposto alla libertà della mia mente.» — Virginia Woolf',pt:'“Não há portão, fechadura ou ferrolho capaz de aprisionar a liberdade da minha mente.” — Virginia Woolf',id:'“Tidak ada gerbang, kunci, atau palang yang dapat membelenggu kebebasan pikiran saya.” — Virginia Woolf',tr:'“Zihnimin özgürlüğüne vurabileceğiniz hiçbir kapı, kilit ya da sürgü yoktur.” — Virginia Woolf',ar:'«لا بوابة ولا قفل ولا مزلاج يمكن وضعه على حرية عقلي.» — فرجينيا وولف'},insight:{uk:'зовнішні обмеження можуть звужувати можливості, але здатність мислити, уявляти й формувати власне судження не повинна автоматично переходити під їхній контроль',ru:'внешние ограничения могут сужать возможности, но способность мыслить, воображать и формировать собственное суждение не должна автоматически переходить под их контроль',pl:'zewnętrzne ograniczenia mogą zawężać możliwości, ale zdolność myślenia, wyobrażania sobie i formułowania własnego sądu nie powinna automatycznie podlegać ich kontroli',en:'external restrictions can narrow our options, but the capacity to think, imagine and form our own judgment need not automatically surrender to them',sv:'yttre begränsningar kan minska våra möjligheter, men förmågan att tänka, föreställa sig och forma ett eget omdöme behöver inte automatiskt underordna sig dem',de:'äußere Grenzen können unsere Möglichkeiten einschränken, doch die Fähigkeit zu denken, sich etwas vorzustellen und ein eigenes Urteil zu bilden muss sich ihnen nicht automatisch unterwerfen',es:'las restricciones externas pueden reducir nuestras opciones, pero la capacidad de pensar, imaginar y formar un juicio propio no tiene por qué quedar automáticamente sometida a ellas',fr:'les contraintes extérieures peuvent réduire nos possibilités, mais notre capacité de penser, d’imaginer et de former notre propre jugement n’a pas à leur céder automatiquement',it:'i limiti esterni possono restringere le possibilità, ma la capacità di pensare, immaginare e formare un giudizio proprio non deve automaticamente sottomettersi a essi',pt:'limitações externas podem reduzir as possibilidades, mas a capacidade de pensar, imaginar e formar um julgamento próprio não precisa se submeter automaticamente a elas',id:'batasan dari luar dapat mempersempit pilihan, tetapi kemampuan untuk berpikir, membayangkan, dan membentuk penilaian sendiri tidak harus otomatis tunduk kepadanya',tr:'dış sınırlamalar seçeneklerimizi daraltabilir; ancak düşünme, hayal etme ve kendi yargımızı oluşturma yeteneğimiz onlara kendiliğinden teslim olmak zorunda değildir',ar:'قد تضيق القيود الخارجية خياراتنا، لكن القدرة على التفكير والتخيّل وتكوين حكمنا الخاص لا ينبغي أن تخضع لها تلقائيًا'}},
 WQ031:{category:'art_science',author:'Leonardo da Vinci',work:'The Notebooks of Leonardo da Vinci, XIX, 1150 (Richter translation)',date:'notebook text c. 1500; Richter translation',original:'Wisdom is the daughter of experience.',original_language:'en',source:'https://en.wikisource.org/wiki/The_Notebooks_of_Leonardo_Da_Vinci/XIX',locator:'Section “Science, its principles and rules”, item 1150',slug:'leonardo-wisdom-experience',concept:'Leonardo da Vinci in a Renaissance workshop, treated through a dignified art-historical portrait. A sketch, a small mechanical model and a failed experiment sit beside a corrected drawing; the scene shows observation becoming understanding through repeated experience.',q:{uk:'«Мудрість — донька досвіду». — Леонардо да Вінчі',ru:'«Мудрость — дочь опыта». — Леонардо да Винчи',pl:'„Mądrość jest córką doświadczenia.” — Leonardo da Vinci',en:'“Wisdom is the daughter of experience.” — Leonardo da Vinci',sv:'”Visdom är erfarenhetens dotter.” — Leonardo da Vinci',de:'„Weisheit ist die Tochter der Erfahrung.“ — Leonardo da Vinci',es:'«La sabiduría es hija de la experiencia». — Leonardo da Vinci',fr:'«La sagesse est fille de l’expérience.» — Léonard de Vinci',it:'«La sapienza è figlia dell’esperienza.» — Leonardo da Vinci',pt:'“A sabedoria é filha da experiência.” — Leonardo da Vinci',id:'“Kebijaksanaan adalah putri dari pengalaman.” — Leonardo da Vinci',tr:'“Bilgelik deneyimin kızıdır.” — Leonardo da Vinci',ar:'«الحكمة ابنة التجربة.» — ليوناردو دا فينشي'},insight:{uk:'справжнє розуміння зростає не лише з теорії, а з уважного спостереження, спроб, помилок і перевірки того, що насправді працює',ru:'настоящее понимание растёт не только из теории, но и из внимательного наблюдения, попыток, ошибок и проверки того, что действительно работает',pl:'prawdziwe zrozumienie wyrasta nie tylko z teorii, lecz także z uważnej obserwacji, prób, błędów i sprawdzania, co naprawdę działa',en:'real understanding grows not only from theory but from close observation, attempts, mistakes and testing what actually works',sv:'verklig förståelse växer inte bara ur teori utan ur noggrann observation, försök, misstag och prövning av vad som faktiskt fungerar',de:'echtes Verständnis wächst nicht nur aus Theorie, sondern aus genauer Beobachtung, Versuchen, Fehlern und der Prüfung dessen, was tatsächlich funktioniert',es:'la comprensión real no nace solo de la teoría, sino también de observar con atención, probar, equivocarse y comprobar qué funciona de verdad',fr:'la compréhension véritable ne naît pas seulement de la théorie, mais aussi de l’observation attentive, des essais, des erreurs et de la vérification de ce qui fonctionne réellement',it:'la comprensione autentica non nasce soltanto dalla teoria, ma anche dall’osservazione attenta, dai tentativi, dagli errori e dalla verifica di ciò che funziona davvero',pt:'a compreensão real não cresce apenas da teoria, mas também da observação atenta, das tentativas, dos erros e da verificação do que realmente funciona',id:'pemahaman yang nyata tidak tumbuh hanya dari teori, tetapi juga dari pengamatan yang cermat, percobaan, kesalahan, dan pengujian atas apa yang benar-benar bekerja',tr:'gerçek anlayış yalnızca teoriden değil, dikkatli gözlemden, denemelerden, hatalardan ve gerçekten neyin işe yaradığını sınamaktan büyür',ar:'الفهم الحقيقي لا ينمو من النظرية وحدها، بل من الملاحظة الدقيقة والمحاولة والخطأ واختبار ما يعمل فعلًا'}}
};

const ARTICLE={
 uk:t=>`${t.q.uk}\n\nУ цій думці ${t.author} не пропонує швидкої мотиваційної формули. Вона виникає в конкретному інтелектуальному контексті — ${t.work} — і набуває ваги саме тому, що говорить про межу між тим, що ми можемо контролювати, і тим, що від нас не залежить. ${cap(t.insight.uk)}.\n\nПрактичний сенс починається з чесної інвентаризації. Варто відокремити факт від власної реакції на нього, а потім запитати: що тут справді в моїй владі — рішення, увага, дисципліна, спосіб відповіді, наступний крок? Це не заперечення труднощів і не спроба прикрасити реальність. Навпаки, така позиція вимагає бачити обставини без самообману.\n\nУ повсякденному житті ця різниця помітна в роботі, навчанні, стосунках і творчості. Ми часто витрачаємо сили на боротьбу з уже наявним фактом, хоча корисніше спрямувати їх на те, що ще можна зробити добре. Малий конкретний крок нерідко повертає більше відчуття опори, ніж довгі роздуми про несправедливість ситуації.\n\nЦитата не обіцяє, що правильне ставлення автоматично змінить світ. Вона нагадує про інше: внутрішня свобода проявляється в тому, як ми поводимося з реальною ситуацією. Саме там думка перестає бути красивим висловом і стає практикою.`,
 ru:t=>`${t.q.ru}\n\nВ этой мысли ${t.author} не предлагает быструю мотивационную формулу. Она существует в конкретном интеллектуальном контексте — ${t.work} — и важна именно потому, что проводит границу между тем, что мы можем контролировать, и тем, что от нас не зависит. ${cap(t.insight.ru)}.\n\nПрактический смысл начинается с честной инвентаризации. Полезно отделить сам факт от своей реакции на него, а затем спросить: что здесь действительно в моей власти — решение, внимание, дисциплина, способ ответа, следующий шаг? Это не отрицание трудностей и не попытка приукрасить реальность. Напротив, такая позиция требует смотреть на обстоятельства без самообмана.\n\nВ повседневной жизни эта разница заметна в работе, учёбе, отношениях и творчестве. Мы нередко тратим силы на борьбу с уже случившимся фактом, хотя продуктивнее направить их на то, что ещё можно сделать хорошо. Небольшое конкретное действие часто возвращает больше опоры, чем долгие размышления о несправедливости ситуации.\n\nЦитата не обещает, что правильное отношение автоматически изменит мир. Она напоминает о другом: внутренняя свобода проявляется в том, как мы обходимся с реальностью. Именно здесь красивая фраза превращается в практику.`,
 pl:t=>`${t.q.pl}\n\nTa myśl ${t.author} nie jest prostym hasłem motywacyjnym. Ma konkretny kontekst — ${t.work} — i nabiera znaczenia dlatego, że oddziela to, na co mamy wpływ, od tego, czego nie możemy dowolnie zmienić. ${cap(t.insight.pl)}.\n\nPraktyczne odczytanie zaczyna się od uczciwego rozpoznania sytuacji. Najpierw warto oddzielić fakt od własnej reakcji, a potem zapytać: co pozostaje w moich rękach — decyzja, uwaga, dyscyplina, sposób odpowiedzi, następny krok? Nie chodzi o zaprzeczanie trudnościom ani o sztuczny optymizm. Chodzi o spojrzenie na rzeczywistość bez upiększeń i bez rezygnacji z własnej sprawczości.\n\nW codziennym życiu widać to w pracy, nauce, relacjach i twórczości. Często tracimy energię na spór z faktem, który już istnieje, zamiast skierować ją na to, co nadal można zrobić dobrze. Mały, konkretny ruch potrafi przywrócić więcej poczucia oparcia niż długie rozważania nad tym, dlaczego sytuacja powinna wyglądać inaczej.\n\nTa cytat nie obiecuje, że właściwa postawa automatycznie zmieni świat. Przypomina raczej, że wolność wewnętrzna ujawnia się w sposobie, w jaki odpowiadamy na to, co realne.`,
 en:t=>`${t.q.en}\n\nThis idea from ${t.author} is not a quick motivational slogan. It belongs to a specific intellectual context — ${t.work} — and matters because it draws a line between what can be influenced and what cannot simply be wished away. ${cap(t.insight.en)}.\n\nThe practical reading starts with an honest inventory. Separate the fact itself from your reaction to it, then ask what remains genuinely yours: a decision, attention, discipline, the manner of response, the next concrete step. This is not denial and it is not forced optimism. It is a way of looking directly at reality without surrendering all agency to it.\n\nThe distinction appears everywhere: work, study, relationships, creative projects, illness, uncertainty, and setbacks. We can spend enormous energy arguing internally with a fact that already exists. Often the more useful move is to redirect that energy toward the part of the situation that can still be handled well. One specific action can restore more orientation than hours spent rehearsing how things should have been.\n\nThe quote does not promise that the right attitude will magically change the world. Its stronger claim is more modest and more demanding: inner freedom is visible in what we do with the reality in front of us. That is where a memorable sentence becomes a practice rather than decoration.`,
 sv:t=>`${t.q.sv}\n\nDen här tanken från ${t.author} är inte en snabb motivationsfras. Den hör hemma i ett tydligt sammanhang — ${t.work} — och blir viktig därför att den skiljer mellan det vi kan påverka och det som inte går att önska bort. ${cap(t.insight.sv)}.\n\nEn praktisk läsning börjar med en ärlig inventering. Skilj själva faktumet från din reaktion och fråga sedan vad som faktiskt fortfarande är ditt: ett beslut, din uppmärksamhet, din disciplin, sättet du svarar på och nästa konkreta steg. Det handlar inte om att förneka svårigheter eller tvinga fram optimism, utan om att se verkligheten tydligt utan att lämna över all handlingskraft till den.\n\nSkillnaden märks i arbete, studier, relationer och skapande. Vi kan lägga stora mängder energi på att protestera inombords mot något som redan har hänt. Ofta är det mer verkningsfullt att rikta den energin mot det som fortfarande går att göra väl. En liten konkret handling kan ge mer riktning än många timmar av tankar om hur situationen borde ha varit.\n\nCitatet lovar inte att rätt inställning automatiskt förändrar världen. Det påminner om att inre frihet blir synlig i hur vi hanterar den verklighet som faktiskt finns framför oss.`,
 de:t=>`${t.q.de}\n\nDieser Gedanke von ${t.author} ist kein schneller Motivationsspruch. Er steht in einem konkreten Zusammenhang — ${t.work} — und gewinnt seine Kraft dadurch, dass er zwischen dem unterscheidet, was wir beeinflussen können, und dem, was sich nicht einfach wegwünschen lässt. ${cap(t.insight.de)}.\n\nDie praktische Lesart beginnt mit einer ehrlichen Bestandsaufnahme. Trenne die Tatsache selbst von deiner Reaktion darauf und frage dann: Was liegt tatsächlich noch bei mir — eine Entscheidung, Aufmerksamkeit, Disziplin, die Art meiner Antwort, der nächste konkrete Schritt? Das ist weder Verdrängung noch erzwungener Optimismus. Es bedeutet, die Wirklichkeit nüchtern zu sehen, ohne ihr die gesamte eigene Handlungsfähigkeit zu überlassen.\n\nDiese Unterscheidung begegnet uns in Arbeit, Lernen, Beziehungen und kreativen Vorhaben. Viel Energie geht verloren, wenn wir innerlich mit einer Tatsache streiten, die längst besteht. Oft ist es sinnvoller, diese Kraft auf den Teil der Lage zu richten, den wir weiterhin gut gestalten können. Eine kleine konkrete Handlung kann mehr Orientierung zurückgeben als stundenlanges Grübeln darüber, wie es hätte sein sollen.\n\nDas Zitat verspricht nicht, dass die richtige Haltung die Welt automatisch verändert. Es erinnert daran, dass innere Freiheit daran sichtbar wird, wie wir mit der realen Situation umgehen.`,
 es:t=>`${t.q.es}\n\nEsta idea de ${t.author} no es una fórmula rápida de motivación. Tiene un contexto concreto — ${t.work} — y resulta valiosa porque distingue entre aquello sobre lo que podemos influir y aquello que no desaparece simplemente porque deseemos otra realidad. ${cap(t.insight.es)}.\n\nLa lectura práctica comienza con un inventario honesto. Conviene separar el hecho de nuestra reacción al hecho y preguntar después qué sigue dependiendo de nosotros: una decisión, la atención, la disciplina, la forma de responder, el siguiente paso concreto. No es negar la dificultad ni fabricar optimismo. Es mirar la realidad de frente sin entregarle toda nuestra capacidad de actuar.\n\nLa diferencia aparece en el trabajo, el aprendizaje, las relaciones y los proyectos creativos. Podemos gastar una enorme cantidad de energía discutiendo mentalmente con algo que ya ocurrió. A menudo es más útil dirigir esa energía hacia la parte de la situación que todavía puede hacerse bien. Una acción pequeña y concreta puede devolver más orientación que horas pensando en cómo deberían haber sido las cosas.\n\nLa cita no promete que una buena actitud cambie el mundo por sí sola. Recuerda algo más exigente: la libertad interior se vuelve visible en la manera en que tratamos con la realidad que tenemos delante.`,
 fr:t=>`${t.q.fr}\n\nCette pensée de ${t.author} n’est pas une formule de motivation rapide. Elle appartient à un contexte précis — ${t.work} — et prend sa force parce qu’elle distingue ce que nous pouvons encore influencer de ce qui ne disparaît pas simplement parce que nous souhaiterions une autre réalité. ${cap(t.insight.fr)}.\n\nLa lecture pratique commence par un inventaire honnête. Il faut séparer le fait lui-même de notre réaction, puis demander ce qui reste réellement entre nos mains : une décision, l’attention, la discipline, la manière de répondre, le prochain geste concret. Il ne s’agit ni de nier la difficulté ni de fabriquer de l’optimisme. Il s’agit de regarder la réalité en face sans lui abandonner toute notre capacité d’action.\n\nCette distinction apparaît dans le travail, l’apprentissage, les relations et les projets créatifs. Nous pouvons dépenser énormément d’énergie à contester intérieurement un fait déjà présent. Il est souvent plus utile de rediriger cette énergie vers la partie de la situation qui peut encore être bien menée. Une petite action concrète peut rendre davantage de direction que des heures passées à imaginer comment les choses auraient dû être.\n\nLa citation ne promet pas qu’une bonne attitude changera automatiquement le monde. Elle rappelle que la liberté intérieure devient visible dans la manière dont nous répondons au réel.`,
 it:t=>`${t.q.it}\n\nQuesta idea di ${t.author} non è una formula motivazionale rapida. Appartiene a un contesto preciso — ${t.work} — e acquista forza perché distingue tra ciò che possiamo ancora influenzare e ciò che non scompare solo perché vorremmo una realtà diversa. ${cap(t.insight.it)}.\n\nLa lettura pratica comincia con un inventario onesto. Separiamo il fatto dalla nostra reazione e chiediamoci che cosa rimane davvero nelle nostre mani: una decisione, l’attenzione, la disciplina, il modo di rispondere, il prossimo passo concreto. Non è negazione e non è ottimismo forzato; è guardare la realtà senza consegnarle tutta la nostra capacità di agire.\n\nQuesta distinzione compare nel lavoro, nello studio, nelle relazioni e nei progetti creativi. Possiamo spendere molta energia discutendo interiormente con un fatto già avvenuto. Spesso è più utile dirigere quella forza verso la parte della situazione che possiamo ancora affrontare bene. Un’azione piccola e concreta può restituire più orientamento di molte ore dedicate a immaginare come avrebbero dovuto andare le cose.\n\nLa citazione non promette che l’atteggiamento giusto cambi automaticamente il mondo. Ricorda piuttosto che la libertà interiore diventa visibile nel modo in cui rispondiamo alla realtà.`,
 pt:t=>`${t.q.pt}\n\nEsta ideia de ${t.author} não é uma fórmula rápida de motivação. Ela pertence a um contexto específico — ${t.work} — e ganha força porque distingue aquilo que ainda podemos influenciar daquilo que não desaparece só porque desejaríamos uma realidade diferente. ${cap(t.insight.pt)}.\n\nA leitura prática começa com um inventário honesto. Vale separar o fato da nossa reação e perguntar o que continua realmente em nossas mãos: uma decisão, a atenção, a disciplina, a forma de responder, o próximo passo concreto. Isso não é negar a dificuldade nem forçar otimismo. É olhar a realidade de frente sem entregar a ela toda a nossa capacidade de agir.\n\nEssa diferença aparece no trabalho, nos estudos, nos relacionamentos e nos projetos criativos. Podemos gastar muita energia discutindo mentalmente com um fato que já existe. Muitas vezes é mais útil direcionar essa energia para a parte da situação que ainda pode ser bem conduzida. Uma ação pequena e concreta pode devolver mais orientação do que horas pensando em como as coisas deveriam ter sido.\n\nA citação não promete que a atitude certa mudará automaticamente o mundo. Ela lembra que a liberdade interior se torna visível na forma como lidamos com a realidade diante de nós.`,
 id:t=>`${t.q.id}\n\nGagasan dari ${t.author} ini bukan slogan motivasi singkat. Ia hadir dalam konteks yang jelas — ${t.work} — dan penting karena membedakan antara hal yang masih dapat kita pengaruhi dan hal yang tidak akan lenyap hanya karena kita menginginkan kenyataan lain. ${cap(t.insight.id)}.\n\nPembacaan yang praktis dimulai dengan melihat keadaan secara jujur. Pisahkan fakta dari reaksi kita terhadap fakta itu, lalu tanyakan apa yang benar-benar masih berada di tangan kita: keputusan, perhatian, disiplin, cara merespons, dan langkah konkret berikutnya. Ini bukan penyangkalan dan bukan optimisme yang dipaksakan. Ini adalah cara menatap kenyataan tanpa menyerahkan seluruh daya bertindak kita kepadanya.\n\nPerbedaan ini tampak dalam pekerjaan, belajar, hubungan, dan proyek kreatif. Kita dapat menghabiskan banyak energi untuk berdebat dalam pikiran dengan sesuatu yang sudah terjadi. Sering kali lebih berguna mengarahkan energi itu pada bagian situasi yang masih dapat kita kerjakan dengan baik. Tindakan kecil yang konkret bisa memberi arah lebih besar daripada berjam-jam memikirkan bagaimana seharusnya keadaan terjadi.\n\nKutipan ini tidak menjanjikan bahwa sikap yang tepat otomatis mengubah dunia. Ia mengingatkan bahwa kebebasan batin terlihat dari cara kita menanggapi kenyataan yang ada di depan kita.`,
 tr:t=>`${t.q.tr}\n\n${t.author} tarafından dile getirilen bu düşünce hızlı bir motivasyon sloganı değildir. Belirli bir bağlama — ${t.work} — aittir ve gücünü, etkileyebileceğimiz şeylerle yalnızca istemekle ortadan kalkmayan şeyler arasındaki ayrımdan alır. ${cap(t.insight.tr)}.\n\nPratik okuma dürüst bir durum tespitiyle başlar. Önce gerçeğin kendisini ona verdiğimiz tepkiden ayırmak, sonra da gerçekten elimizde ne kaldığını sormak gerekir: bir karar, dikkatimiz, disiplinimiz, yanıt verme biçimimiz, bir sonraki somut adım. Bu ne zorluğu inkâr etmektir ne de zoraki iyimserliktir. Gerçekliğe doğrudan bakarken bütün hareket alanımızı ona teslim etmemektir.\n\nBu ayrım işte, öğrenmede, ilişkilerde ve yaratıcı projelerde sürekli karşımıza çıkar. Zaten gerçekleşmiş bir olguyla zihnimizde tartışarak büyük enerji kaybedebiliriz. Çoğu zaman bu enerjiyi hâlâ iyi yapabileceğimiz şeye yöneltmek daha yararlıdır. Küçük ama somut bir adım, olayların nasıl olması gerektiğini düşünerek geçirilen saatlerden daha fazla yön duygusu verebilir.\n\nAlıntı, doğru tutumun dünyayı kendiliğinden değiştireceğini vaat etmez. İçsel özgürlüğün, önümüzdeki gerçekliğe nasıl karşılık verdiğimizde görünür olduğunu hatırlatır.`,
 ar:t=>`${t.q.ar}\n\nهذه الفكرة لدى ${t.author} ليست شعارًا تحفيزيًا سريعًا. فهي تأتي في سياق محدد — ${t.work} — وتكتسب قوتها من التمييز بين ما يمكننا التأثير فيه وما لا يختفي لمجرد أننا نتمنى واقعًا آخر. ${cap(t.insight.ar)}.\n\nتبدأ القراءة العملية بجرد صادق للواقع. نفصل بين الحقيقة نفسها ورد فعلنا عليها، ثم نسأل: ما الذي يبقى فعلًا في أيدينا؟ قرار، انتباه، انضباط، طريقة الاستجابة، والخطوة الملموسة التالية. هذا ليس إنكارًا للصعوبة ولا تفاؤلًا قسريًا، بل مواجهة للواقع من دون تسليمه كل قدرتنا على الفعل.\n\nيظهر هذا الفرق في العمل والتعلّم والعلاقات والمشاريع الإبداعية. قد نهدر قدرًا كبيرًا من الطاقة في مجادلة أمر وقع بالفعل. وغالبًا يكون الأجدى توجيه هذه الطاقة إلى الجزء الذي ما زال بإمكاننا التعامل معه جيدًا. خطوة صغيرة ومحددة قد تعيد إلينا الاتجاه أكثر من ساعات نقضيها في التفكير في الكيفية التي كان ينبغي أن تسير بها الأمور.\n\nلا تعدنا العبارة بأن الموقف الصحيح سيغيّر العالم تلقائيًا. إنها تذكّرنا بأن الحرية الداخلية تظهر في الطريقة التي نتعامل بها مع الواقع الموجود أمامنا.`
};

function cap(s){s=String(s||'');return s?s.charAt(0).toUpperCase()+s.slice(1):s}
function baseQuote(s){return String(s||'').replace(/\s+[—-]\s+[^—]+$/,'').trim()}
function authorFromQuote(s,fallback){const m=String(s||'').match(/[—-]\s*([^—]+)$/);return m?m[1].trim():fallback}
function slugFor(t){return t.slug}
async function ensureOutputs(env){await env.DB.prepare(`CREATE TABLE IF NOT EXISTS content_outputs (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,content_item_id TEXT NOT NULL,language_code TEXT NOT NULL,output_key TEXT NOT NULL,output_text TEXT,status TEXT NOT NULL DEFAULT 'draft',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(content_item_id,language_code,output_key))`).run()}
async function upsertOut(env,id,lang,key,text,ts){await env.DB.prepare(`INSERT INTO content_outputs(id,project_id,content_item_id,language_code,output_key,output_text,status,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(content_item_id,language_code,output_key) DO UPDATE SET output_text=excluded.output_text,status=excluded.status,updated_at=excluded.updated_at`).bind(`${id}_${lang}_${key}`,PROJECT,id,lang,key,text,'ready',ts).run()}

function videoPrompt(lang,t){return `Create a premium photorealistic vertical 9:16 cinematic video in ${lang}.\n\n${t.concept}\n\nShow the exact localized quote in one stable, large, elegant text card in the upper-middle safe area:\n${t.q[lang]}\n\nAudio: a calm native ${lang} narrator reads the exact quote and attribution naturally and completely, with correct native pronunciation of ${authorFromQuote(t.q[lang],t.author)}. Restrained cinematic music remains below the voice.\n\nNo subtitles. No captions. No emoji. No decorative symbols. No logo. No branding. No watermark. No other readable text.\n\nEnd on a clean contemplative hold.`}
function pinPrompt(lang,t){return `Create a premium photorealistic vertical 2:3 Pinterest image, target 1000×1500. ${t.concept} ${VISUAL[lang]} The result must feel distinct from the other locale versions while preserving the same meaning and premium Wise Quotes World tone. Leave generous clean space for large mobile-readable typography. Render EXACT text: ${t.q[lang]} No CTA on the image. No other readable text. No flag. No national emblem. No logo. No branding. No watermark.`}
function article(lang,t){return ARTICLE[lang](t)}
function excerpt(text,max=430){const s=String(text||'').replace(/\n+/g,' ').trim();if(s.length<=max)return s;return s.slice(0,max).replace(/\s+\S*$/,'').trim()+'…'}
function social(lang,t,url){const q=t.q[lang],ins=cap(t.insight[lang]),u=UI[lang],body=article(lang,t),short=excerpt(body.replace(q,''),420),tags=TAGS[lang];const facebook=`${q}\n\n${short}\n\n${u.more}:\n${url}\n\n${tags}`;const instagram=`${q}\n\n${ins}. ${u.question}\n\n${u.profile}\n\n${tags}`;const tiktok=`${q}\n\n${ins}.\n\n${u.site}\n\n${tags}`;const threads=[`${q}\n\n${ins}.\n\n${url}`,`${ins}. Іноді одна точна думка корисніша за десяток порад.\n\n${url}`,`${u.question}\n\n${q}\n\n${url}`];const title=`${authorFromQuote(q,t.author)} — ${baseQuote(q).replace(/[«»„”“]/g,'').slice(0,68)}`;return{facebook,instagram,tiktok,threads:threads.join('\n\n---\n\n'),youtube_title:title,youtube_description:`${q}\n\n${ins}. ${u.profile}\n\n${tags}`,pinterest_title:title.slice(0,95),pinterest_description:`${baseQuote(q)} ${ins}. A concise reflection on ${t.author} and the meaning of this verified quote.`,pinterest_video_title:title.slice(0,95),pinterest_video_description:`${ins}. This video pin presents the verified ${t.author} quote in the ${lang.toUpperCase()} locale and leads to the full same-language reflection.`}}

async function ensureItem(env,id,t,ts){const existing=await env.DB.prepare(`SELECT id FROM content_items WHERE project_id=? AND id=?`).bind(PROJECT,id).first();if(!existing){const seq=Number(id.slice(2));await env.DB.prepare(`INSERT INTO content_items(id,project_id,content_type,sequence_no,category,canonical_title,source_text,source_name,source_url,status,facts_verified,uniqueness_verified,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,PROJECT,'quote',seq,t.category,`${t.author} — ${t.original}`,t.original,t.author,t.source,'idea',0,0,'Prepared ten-day editorial buffer.',ts,ts).run()}}
async function prepareTopic(env,id,t){const ts=TS();await ensureOutputs(env);await ensureItem(env,id,t,ts);const ev=await env.DB.prepare(`SELECT id FROM quote_source_evidence WHERE content_item_id=? AND source_url=? LIMIT 1`).bind(id,t.source).first();if(!ev)await env.DB.prepare(`INSERT INTO quote_source_evidence(content_item_id,source_type,source_title,source_url,source_locator,original_text,original_language,verified,verification_notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(id,'primary_or_authoritative_text',`${t.author}, ${t.work}`,t.source,t.locator,t.original,t.original_language,1,'Source wording and locus cross-checked during 2026-09-10 ten-day buffer audit; three-pass localization review performed before DB write.',ts).run();
 await env.DB.prepare(`UPDATE content_items SET canonical_title=?,source_text=?,source_name=?,source_url=?,quote_type='verbatim',original_quote=?,original_language=?,author_name=?,author_source=?,source_work=?,source_date=?,attribution_status='verified',facts_verified=1,uniqueness_verified=1,source_verified_at=?,source_verification_notes=?,category=?,category_slug=?,status='localized',notes=?,updated_at=? WHERE project_id=? AND id=?`).bind(`${t.author} — ${t.original}`,t.original,t.author,t.source,t.original,t.original_language,t.author,t.source,t.work,t.date,ts,'Verified source; quote length reviewed; 13 website localizations and 8 connected-social localizations reviewed in three editorial passes.',t.category,t.category,'Complete pre-media package being prepared under current MASTER_RULES.',ts,PROJECT,id).run();
 for(const lang of WEB){const q=t.q[lang],vid=`${id}_${lang}_v1`,prompt=SOCIAL.includes(lang)?videoPrompt(lang,t):null;await env.DB.prepare(`INSERT INTO content_versions(id,content_id,language_code,title,adapted_text,voiceover_text,on_screen_text,ai_prompt,status,language_check_status,approved,verification_date,source_urls,editor_notes,version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1) ON CONFLICT(content_id,language_code,version) DO UPDATE SET title=excluded.title,adapted_text=excluded.adapted_text,voiceover_text=excluded.voiceover_text,on_screen_text=excluded.on_screen_text,ai_prompt=excluded.ai_prompt,status=excluded.status,language_check_status=excluded.language_check_status,approved=excluded.approved,verification_date=excluded.verification_date,source_urls=excluded.source_urls,editor_notes=excluded.editor_notes`).bind(vid,id,lang,`${authorFromQuote(q,t.author)} — ${baseQuote(q)}`,q,q,q,prompt,'native_language_qa','native_qa_pass',1,ts,t.source,'Three-pass semantic-fidelity/native-naturalness editorial review completed; punctuation and attribution rechecked.').run();const path=`/${lang}/quotes/${slugFor(t)}/`,body=article(lang,t);await env.DB.prepare(`INSERT INTO quote_pages(id,project_id,content_item_id,content_version_id,language_code,slug,seo_title,meta_description,reflection_title,reflection_body,canonical_path,status,published_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(content_version_id) DO UPDATE SET slug=excluded.slug,seo_title=excluded.seo_title,meta_description=excluded.meta_description,reflection_title=excluded.reflection_title,reflection_body=excluded.reflection_body,canonical_path=excluded.canonical_path,status=CASE WHEN quote_pages.status='published' THEN 'published' ELSE excluded.status END,updated_at=excluded.updated_at`).bind(`QP_${id}_${lang}`,PROJECT,id,vid,lang,slugFor(t),`${authorFromQuote(q,t.author)} — ${baseQuote(q).slice(0,100)}`,`${authorFromQuote(q,t.author)}: ${t.insight[lang]}. Verified quote, source and reflection.`,UI[lang]?.meaning||'Meaning and context',body,path,'draft',null,ts).run()}
 const pub=await publishWebsite(env,id);if(!pub?.published)return{ok:false,id,error:'website publication gate failed',pub};
 for(const lang of SOCIAL){const url=`https://wisequotesworld.com/${lang}/quotes/${slugFor(t)}/`,s=social(lang,t,url),outs={pinterest_prompt:pinPrompt(lang,t),facebook:s.facebook,instagram:s.instagram,threads:s.threads,tiktok:s.tiktok,youtube_title:s.youtube_title,youtube_description:s.youtube_description,pinterest_title:s.pinterest_title,pinterest_description:s.pinterest_description,pinterest_video_title:s.pinterest_video_title,pinterest_video_description:s.pinterest_video_description,website_reflection:article(lang,t),article_url:url};for(const [key,text] of Object.entries(outs))await upsertOut(env,id,lang,key,text,ts)}
 await env.DB.prepare(`UPDATE content_versions SET status='media_pending',updated_at=? WHERE content_id=?`).bind(ts,id).run();await env.DB.prepare(`UPDATE content_items SET status='media_pending',notes=?,updated_at=? WHERE project_id=? AND id=?`).bind('Complete pre-media package: verified source; 13 technically published/indexable website articles; 13 three-pass locale QA records; 8 video prompts; differentiated Pinterest image prompts; platform copy ready. Awaiting user media upload.',ts,PROJECT,id).run();return{ok:true,id,published:true,status:'media_pending'} }

const EXISTING={
 WQ022:{author:'Albert Einstein',scene:'A quiet late-1920s study with no living historical person on screen. A small static bronze museum bust of an early-20th-century theoretical physicist with unruly hair sits on a bookshelf in partial shadow and remains an inanimate sculpture throughout. Chalk equations reach the edge of a blackboard while an open window reveals a vast star field, making imagination the visual bridge beyond established knowledge.'},
 WQ023:{author:'Lesya Ukrainka',scene:'A dignified art-historical portrait of Lesya Ukrainka in a spring landscape emerging from late frost. Small flowers push through cold ground while warm light reaches the horizon: active hope without sentimentality.'},
 WQ024:{author:'John F. Kennedy',scene:'A restrained 1961 civic setting with a dignified Kennedy portrait. Citizens pass a light forward from one person to another, turning responsibility into visible service.'},
 WQ025:{author:'Rabindranath Tagore',scene:'A dignified Tagore portrait beside an open threshold at dawn. A bowed silhouette slowly raises its head as walls recede into open sky, expressing intellectual and moral freedom.'},
 WQ026:{author:'Michel de Montaigne',scene:'Montaigne in a quiet Renaissance tower library. An unfinished manuscript lies beside ordinary objects of daily life; moving sunlight suggests that living itself is the work and the art.'}
};
async function refreshExistingPinterest(env,id,cfg){const ts=TS();for(const lang of SOCIAL){const v=await env.DB.prepare(`SELECT adapted_text FROM content_versions WHERE content_id=? AND language_code=? ORDER BY version DESC LIMIT 1`).bind(id,lang).first();if(!v?.adapted_text)continue;const prompt=`Create a premium photorealistic vertical 2:3 Pinterest image, target 1000×1500. ${cfg.scene} ${VISUAL[lang]} The ${lang.toUpperCase()} composition must be visibly distinct from the other locale versions while preserving the quote meaning and premium Wise Quotes World tone. Leave generous clean space for large mobile-readable typography. Render EXACT text: ${v.adapted_text} No CTA on the image. No other readable text. No flag. No national emblem. No logo. No branding. No watermark.`;await upsertOut(env,id,lang,'pinterest_prompt',prompt,ts);const ptitle=await env.DB.prepare(`SELECT output_text FROM content_outputs WHERE project_id=? AND content_item_id=? AND language_code=? AND output_key='pinterest_title' LIMIT 1`).bind(PROJECT,id,lang).first();const pdesc=await env.DB.prepare(`SELECT output_text FROM content_outputs WHERE project_id=? AND content_item_id=? AND language_code=? AND output_key='pinterest_description' LIMIT 1`).bind(PROJECT,id,lang).first();await upsertOut(env,id,lang,'pinterest_video_title',ptitle?.output_text||`${cfg.author} — video quote`,ts);await upsertOut(env,id,lang,'pinterest_video_description',`${pdesc?.output_text||''} Video version uses the approved 9:16 locale video; destination remains the exact same-language article URL.`.trim(),ts)}return{ok:true,id}}

export async function prepareBuffer022031(env){if(!env?.DB)return{ok:false,error:'DB unavailable'};await ensureOutputs(env);const refreshed=[];for(const [id,cfg] of Object.entries(EXISTING))refreshed.push(await refreshExistingPinterest(env,id,cfg));const prepared=[];for(const [id,t] of Object.entries(TOPICS)){const r=await prepareTopic(env,id,t);prepared.push(r);if(!r.ok)return{ok:false,failed:id,refreshed,prepared,readback:await readBuffer022031(env)}}return{ok:true,refreshed,prepared,readback:await readBuffer022031(env)}}

export async function readBuffer022031(env){if(!env?.DB)return{ok:false,error:'DB unavailable'};await ensureOutputs(env);const rows=[];for(let n=22;n<=31;n++){const id=`WQ${String(n).padStart(3,'0')}`;const item=await env.DB.prepare(`SELECT id,status,quote_type,author_name,attribution_status,facts_verified FROM content_items WHERE project_id=? AND id=?`).bind(PROJECT,id).first();const pages=await env.DB.prepare(`SELECT COUNT(*) c FROM quote_pages WHERE project_id=? AND content_item_id=? AND status='published'`).bind(PROJECT,id).first();const vers=await env.DB.prepare(`SELECT COUNT(*) c FROM content_versions WHERE content_id=? AND language_check_status='native_qa_pass'`).bind(id).first();const prompts=await env.DB.prepare(`SELECT COUNT(*) c FROM content_versions WHERE content_id=? AND language_code IN ('uk','ru','pl','en','sv','de','es','fr') AND TRIM(COALESCE(ai_prompt,''))<>''`).bind(id).first();const outs=await env.DB.prepare(`SELECT COUNT(*) c FROM content_outputs WHERE project_id=? AND content_item_id=? AND language_code IN ('uk','ru','pl','en','sv','de','es','fr') AND TRIM(COALESCE(output_text,''))<>''`).bind(PROJECT,id).first();const pins=await env.DB.prepare(`SELECT COUNT(*) c FROM content_outputs WHERE project_id=? AND content_item_id=? AND output_key='pinterest_prompt' AND language_code IN ('uk','ru','pl','en','sv','de','es','fr') AND TRIM(COALESCE(output_text,''))<>''`).bind(PROJECT,id).first();const ready=Number(pages?.c||0)===13&&Number(vers?.c||0)>=13&&Number(prompts?.c||0)===8&&Number(pins?.c||0)===8&&Number(outs?.c||0)>=88&&item?.attribution_status==='verified';rows.push({...item,published_pages:Number(pages?.c||0),native_qa:Number(vers?.c||0),video_prompts:Number(prompts?.c||0),outputs:Number(outs?.c||0),pinterest_prompts:Number(pins?.c||0),ready_for_user_media:ready})}return{ok:rows.length===10&&rows.every(x=>x.ready_for_user_media),count:rows.length,rows}}
